CREATE VIEW IF NOT EXISTS `toxicology`.`bond` AS SELECT `bond_id`, `molecule_id`, `bond_type` FROM `bird_minidev_olap`.`ods_toxicology_bond` WHERE COALESCE(`__deleted`, false) = false;
CREATE VIEW IF NOT EXISTS `toxicology`.`connected` AS SELECT `atom_id`, `atom_id2`, `bond_id` FROM `bird_minidev_olap`.`ods_toxicology_connected` WHERE COALESCE(`__deleted`, false) = false;
CREATE VIEW IF NOT EXISTS `toxicology`.`molecule` AS SELECT `molecule_id`, `label` FROM `bird_minidev_olap`.`ods_toxicology_molecule` WHERE COALESCE(`__deleted`, false) = false;